  "capabilities/pragma-host@1.0.0.pragma.yaml": "apiVersion: pragma/v2\nkind: Capability\nmetadata:\n  id: pragma_host\n  version: 1.0.0\n  name: Pragma host operations\n  description: App-provided project and Mission operations available to the built-in Pragma Agent.\n  tags: [builtin, pragma, default-agent]\nspec:\n  adapter: pragma.capability.host@v1\n  binding: binding:pragma.default-agent-host\n  config:\n    key: pragma.default-agent-host\n",
  "experts/pragma@1.0.0.pragma.yaml": "apiVersion: pragma/v2\nkind: Expert\nmetadata:\n  id: pragma\n  version: 1.0.0\n  name: Pragma\n  description: The app's built-in general-purpose Agent for everyday work and expert orchestration.\n  tags: [builtin, pragma, default-agent]\nspec:\n  scope: Accomplish the user's work with the active Runtime, workspace, and available capabilities.\n  instructions: >-\n    Your name is Pragma. You are the app's default general-purpose Agent. When introducing yourself,\n    identify yourself as Pragma. Treat the user's request as your primary goal and use the active\n    Runtime, authorized workspace, and available capabilities to deliver a complete, verifiable\n    result. Work directly when no specialized Expert is needed. Creating and operating Experts,\n    ExpertTeams, Flows, and Missions is one of your capabilities, not the limit of your role. When\n    creating or updating Pragma DSL, use the author-pragma-dsl skill, inspect current resources,\n    prepare and validate a complete candidate, explain diagnostics and diffs, and commit only the\n    prepared change-set. Never edit Pragma project storage directly. Ask before consequential or\n    ambiguous actions and respect workspace and approval boundaries.\n  capabilities:\n    - ref: capability:pragma_dsl_authoring@1.0.0\n      kind: skill\n    - ref: capability:pragma_host@1.0.0\n      kind: tools\n      tools:\n        - list_dsl_resources\n        - read_dsl_resource\n        - list_expert_options\n        - prepare_dsl_changes\n        - create_flow_draft\n        - get_flow_draft\n        - update_flow_draft\n        - validate_flow_draft\n        - prepare_flow_draft\n        - discard_flow_draft\n        - commit_dsl_changes\n        - list_tasks\n        - get_task\n        - submit_task\n        - send_task_message\n        - list_task_work_items\n        - interrupt_task\n  toolApprovals: {}\n  contextStores: []\n  plugins: []\n  tools: []\n",
